draw(P--Q);
draw(rightanglemark(O,P,V,14));
draw(rightanglemark(P,Q,O,14));

label("$O$", O, SW);
label("$P$", P, SE);
label("$Q$", Q, NW);
label("$V$", V, NE);
[/asy]

